def find_similar_sets(test_cases):
    results = []
    for sets in test_cases:
        n = sets[0]
        sets_list = sets[1:]
        similar_found = False
        for i in range(n):
            for j in range(i + 1, n):
                set1 = sets_list[i]
                set2 = sets_list[j]
                intersection = set(set1[1:]) & set(set2[1:])
                if len(intersection) >= 2:
                    results.append((i + 1, j + 1))
                    similar_found = True
                    break
            if similar_found:
                break
        if not similar_found:
            results.append(-1)
    return results

